import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './App.css';

function Contacto() {
  const [formData, setFormData] = useState({
    nombre: '',
    email: '',
    mensaje: ''
  });

  const [mensaje, setMensaje] = useState('');

  const handleChange = (e) => {
    setFormData({...formData, [e.target.name]: e.target.value});
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    for (const key in formData) {
      if (!formData[key]) {
        setMensaje('Todos los campos son obligatorios.');
        return;
      }
    }
    // Aquí iría envío al backend
    console.log('Mensaje enviado:', formData);
    setMensaje('Mensaje enviado correctamente!');
    setFormData({nombre:'', email:'', mensaje:''});
  };

  return (
    <div>
      <header>
        <div className="logo-contenedor">
          <img src="/Logotipo.jpg" alt="Logo Taller Robledo" className="logo" />
          <div className="texto-logo">
            <span className="slogan">FABRICACIÓN DE VOLCOS</span>
            <span className="nombre">TALLER ROBLEDO</span>
          </div>
        </div>
        <nav>
          <ul className="menu">
            <li><Link to="/">Inicio</Link></li>
            <li><Link to="/volcos">Volcos</Link></li>
            <li><Link to="/cotizacion">Cotización</Link></li>
            <li><Link to="/contacto" className="active">Contacto</Link></li>
            <li><Link to="/opiniones">Opiniones</Link></li>
            <li><Link to="/registro">Registro</Link></li>
          </ul>
        </nav>
      </header>

      <main>
        <h1>Contáctenos</h1>
        <p><strong>Teléfono:</strong> 3148805733</p>
        <p><strong>Dirección:</strong> Carrera 3 Norte # 55 - 04, Barrio Alcázares</p>
        <p><strong>Ciudad:</strong> Cartago, Valle</p>
        <p><strong>Email:</strong> jesushernandocardona@hotmail.com</p>

        <div className="mensaje-contenedor">
          <h3>Envíanos un mensaje</h3>
          <form className="form-contacto" onSubmit={handleSubmit}>
            <input
              type="text"
              name="nombre"
              placeholder="Tu nombre"
              value={formData.nombre}
              onChange={handleChange}
              required
            />
            <input
              type="email"
              name="email"
              placeholder="Tu correo"
              value={formData.email}
              onChange={handleChange}
              required
            />
            <textarea
              name="mensaje"
              placeholder="Escribe tu mensaje aquí..."
              value={formData.mensaje}
              onChange={handleChange}
              required
            ></textarea>
            <button type="submit" className="btn-primary">ENVIAR</button>
            {mensaje && <p className="mensaje-form">{mensaje}</p>}
          </form>
        </div>
      </main>

      <footer className="footer">
        <div className="footer-left">
          <p>Taller Robledo | 📞 314 880 5733</p>
        </div>
        <div className="footer-right">
          <p>© 2025 Todos los derechos reservados</p>
        </div>
      </footer>
    </div>
  );
}

export default Contacto;
